def test_template_to_rule_payload_all_conditions():
    tpl = {
        "name": "AllConds",
        "conditions": {
            "sender_contains": ["a.com"],
            "subject_contains": ["hello"],
            "body_contains": ["world"],
            "from_addresses": ["user@a.com"],
            "has_attachments": True,
            "importance": "high",
        },
        "actions": {"mark_as_read": True},
    }
    p = rules.template_to_rule_payload(tpl)
    conds = p["conditions"]
    assert conds["senderContains"] == ["a.com"]
    assert conds["subjectContains"] == ["hello"]
    assert conds["bodyContains"] == ["world"]
    assert conds["fromAddresses"] == [{"emailAddress": {"address": "user@a.com"}}]
    assert conds["hasAttachments"] is True
    assert conds["importance"] == "high"


