def test_validate_template_requires_condition_and_action():
    assert rules.validate_template({"name": "x"}) != []
    assert (
        rules.validate_template(
            {
                "name": "x",
                "conditions": {"sender_contains": ["a"]},
                "actions": {"mark_as_read": True},
            }
        )
        == []
    )


def test_validate_template_missing_name():
    errs = rules.validate_template(
        {"conditions": {"sender_contains": ["a"]}, "actions": {"mark_as_read": True}}
    )
    assert any("name" in e.lower() for e in errs)


def test_validate_template_no_conditions():
    errs = rules.validate_template(
        {"name": "x", "conditions": {}, "actions": {"mark_as_read": True}}
    )
    assert any("condition" in e.lower() for e in errs)


