def test_validate_template_importance_valid_values():
    for val in ("low", "normal", "high", "Low", "HIGH"):
        errs = rules.validate_template(
            {
                "name": "x",
                "conditions": {"importance": val},
                "actions": {"mark_as_read": True},
            }
        )
        assert errs == [], f"Expected valid for importance={val!r}, got {errs}"


