def test_rule_to_template_basic():
    rule = {
        "displayName": "My Rule",
        "sequence": 3,
        "isEnabled": True,
        "conditions": {
            "senderContains": ["acme.com"],
            "subjectContains": ["invoice"],
        },
        "actions": {
            "moveToFolder": "FolderID123",
            "markAsRead": True,
        },
    }
    tpl = rules.rule_to_template(rule)
    assert tpl["name"] == "My Rule"
    assert tpl["sequence"] == 3
    assert tpl["enabled"] is True
    assert tpl["conditions"]["sender_contains"] == ["acme.com"]
    assert tpl["conditions"]["subject_contains"] == ["invoice"]
    assert tpl["actions"]["move_to"] == "FolderID123"
    assert tpl["actions"]["mark_as_read"] is True


def test_rule_to_template_with_folder_namer():
    rule = {
        "displayName": "Named",
        "isEnabled": True,
        "conditions": {"senderContains": ["x.com"]},
        "actions": {"moveToFolder": "ID::Newsletters", "copyToFolder": "ID::Archive"},
    }
    tpl = rules.rule_to_template(rule, folder_namer=lambda fid: fid.replace("ID::", ""))
    assert tpl["actions"]["move_to"] == "Newsletters"
    assert tpl["actions"]["copy_to"] == "Archive"


