def test_round_trip_preserves_semantics():
    tpl = {
        "name": "RT Test",
        "enabled": True,
        "sequence": 7,
        "conditions": {
            "sender_contains": ["round.com"],
            "subject_contains": ["trip"],
        },
        "actions": {
            "move_to": "Trips",
            "mark_as_read": True,
            "assign_categories": ["Travel"],
            "stop_processing": True,
        },
    }
    payload = rules.template_to_rule_payload(tpl)
    # Inject an id so rule_to_template gets a realistic rule dict
    payload["id"] = "fake-id"
    payload["displayName"] = payload["displayName"]  # already set

    recovered = rules.rule_to_template(payload)

    assert recovered["name"] == tpl["name"]
    assert recovered["enabled"] == tpl["enabled"]
    assert recovered["sequence"] == tpl["sequence"]
    assert (
        recovered["conditions"]["sender_contains"]
        == tpl["conditions"]["sender_contains"]
    )
    assert (
        recovered["conditions"]["subject_contains"]
        == tpl["conditions"]["subject_contains"]
    )
    assert recovered["actions"]["move_to"] == tpl["actions"]["move_to"]
    assert recovered["actions"]["mark_as_read"] == tpl["actions"]["mark_as_read"]
    assert (
        recovered["actions"]["assign_categories"] == tpl["actions"]["assign_categories"]
    )
    assert recovered["actions"]["stop_processing"] == tpl["actions"]["stop_processing"]
